from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

def write(path, content):
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8', newline='\n')

write('tools/repo-autopull-exe/main.go', 'package main\n\nimport (\n    _ "embed"\n    "fmt"\n    "io"\n    "os"\n    "os/exec"\n    "path/filepath"\n)\n\nconst (\n    portableConfigName = "RepoAutoPull.config.json"\n    legacyConfigName   = "Repo-AutoPull.config.json"\n)\n\n//go:embed embedded.ps1\nvar embeddedScript []byte\n\nfunc fileExists(path string) bool {\n    info, err := os.Stat(path)\n    return err == nil && !info.IsDir()\n}\n\nfunc copyFile(src, dst string) error {\n    in, err := os.Open(src)\n    if err != nil {\n        return err\n    }\n    defer in.Close()\n\n    out, err := os.OpenFile(dst, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)\n    if err != nil {\n        return err\n    }\n    ok := false\n    defer func() {\n        _ = out.Close()\n        if !ok {\n            _ = os.Remove(dst)\n        }\n    }()\n\n    if _, err := io.Copy(out, in); err != nil {\n        return err\n    }\n    if err := out.Sync(); err != nil {\n        return err\n    }\n    if err := out.Close(); err != nil {\n        return err\n    }\n    ok = true\n    return nil\n}\n\nfunc configCandidates(exeDir string) []string {\n    candidates := []string{\n        filepath.Join(exeDir, legacyConfigName),\n    }\n\n    appData := os.Getenv("APPDATA")\n    if appData == "" {\n        if cfg, err := os.UserConfigDir(); err == nil {\n            appData = cfg\n        }\n    }\n    if appData != "" {\n        candidates = append(candidates, filepath.Join(appData, "RepoAutoPull", legacyConfigName))\n    }\n    return candidates\n}\n\nfunc ensurePortableConfig(exeDir string) (string, error) {\n    configPath := filepath.Join(exeDir, portableConfigName)\n\n    // Repo AutoPull must remain portable. Refuse to silently fall back to a\n    // shared profile when the EXE folder cannot be written.\n    probe, err := os.CreateTemp(exeDir, ".repoautopull-write-test-*")\n    if err != nil {\n        return "", fmt.Errorf("the folder containing RepoAutoPull.exe is not writable (%s). Move/copy the EXE to a writable folder: %w", exeDir, err)\n    }\n    probePath := probe.Name()\n    _ = probe.Close()\n    _ = os.Remove(probePath)\n\n    if fileExists(configPath) {\n        return configPath, nil\n    }\n\n    for _, legacyPath := range configCandidates(exeDir) {\n        if !fileExists(legacyPath) {\n            continue\n        }\n        if err := copyFile(legacyPath, configPath); err != nil {\n            return "", fmt.Errorf("could not migrate legacy configuration from %s: %w", legacyPath, err)\n        }\n        fmt.Printf("Repo AutoPull: migrated configuration to %s\\n", configPath)\n        return configPath, nil\n    }\n\n    return configPath, nil\n}\n\nfunc main() {\n    exePath, err := os.Executable()\n    if err != nil {\n        fmt.Fprintln(os.Stderr, "Repo AutoPull: could not determine executable path:", err)\n        os.Exit(1)\n    }\n    exeDir := filepath.Dir(exePath)\n\n    configPath, err := ensurePortableConfig(exeDir)\n    if err != nil {\n        fmt.Fprintln(os.Stderr, "Repo AutoPull:", err)\n        os.Exit(1)\n    }\n\n    tempRoot, err := os.MkdirTemp("", "RepoAutoPull-")\n    if err != nil {\n        fmt.Fprintln(os.Stderr, "Repo AutoPull: could not create temporary folder:", err)\n        os.Exit(1)\n    }\n    defer os.RemoveAll(tempRoot)\n\n    scriptPath := filepath.Join(tempRoot, "Repo-AutoPull.ps1")\n    if err := os.WriteFile(scriptPath, embeddedScript, 0o600); err != nil {\n        fmt.Fprintln(os.Stderr, "Repo AutoPull: could not prepare embedded script:", err)\n        os.Exit(1)\n    }\n\n    args := []string{"-NoLogo", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", scriptPath}\n    args = append(args, os.Args[1:]...)\n\n    cmd := exec.Command("powershell.exe", args...)\n    cmd.Stdin = os.Stdin\n    cmd.Stdout = os.Stdout\n    cmd.Stderr = os.Stderr\n    cmd.Dir = exeDir\n\n    env := os.Environ()\n    env = append(env,\n        "REPO_AUTOPULL_CONFIG_ROOT="+exeDir,\n        "REPO_AUTOPULL_CONFIG_PATH="+configPath,\n    )\n    cmd.Env = env\n\n    if err := cmd.Run(); err != nil {\n        if exitErr, ok := err.(*exec.ExitError); ok {\n            os.Exit(exitErr.ExitCode())\n        }\n        fmt.Fprintln(os.Stderr, "Repo AutoPull: failed to launch Windows PowerShell:", err)\n        os.Exit(1)\n    }\n}\n')
write('tools/repo-autopull-exe/build.ps1', 'param(\n    [switch]$RefreshResources\n)\n\n$ErrorActionPreference = \'Stop\'\n\n$ToolDir = Split-Path -Parent $MyInvocation.MyCommand.Path\n$RepoRoot = Resolve-Path (Join-Path $ToolDir \'..\\..\')\n$ScriptSource = Join-Path $RepoRoot \'Repo_AutoPull\\Repo-AutoPull.ps1\'\n$EmbeddedScript = Join-Path $ToolDir \'embedded.ps1\'\n$Output = Join-Path $RepoRoot \'Repo_AutoPull\\RepoAutoPull.exe\'\n$Icon = Join-Path $RepoRoot \'Repo_AutoPull\\assets\\RepoAutoPull.ico\'\n$ResourceObject = Join-Path $ToolDir \'rsrc_windows_amd64.syso\'\n\nif (-not (Get-Command go -ErrorAction SilentlyContinue)) {\n    throw \'Go was not found on PATH.\'\n}\nif (-not (Test-Path -LiteralPath $ScriptSource -PathType Leaf)) {\n    throw "Repo AutoPull script not found: $ScriptSource"\n}\nif (-not (Test-Path -LiteralPath $Icon -PathType Leaf)) {\n    throw "Repo AutoPull icon not found: $Icon"\n}\n\nCopy-Item -LiteralPath $ScriptSource -Destination $EmbeddedScript -Force\ntry {\n    Push-Location $ToolDir\n    try {\n        $env:GOOS = \'windows\'\n        $env:GOARCH = \'amd64\'\n        $env:CGO_ENABLED = \'0\'\n\n        if ($RefreshResources -or -not (Test-Path -LiteralPath $ResourceObject -PathType Leaf)) {\n            Write-Host \'Refreshing embedded Windows icon/version resources...\' -ForegroundColor Cyan\n            & go run github.com/tc-hib/go-winres@v0.3.3 simply `\n                --arch amd64 `\n                --out rsrc `\n                --icon $Icon `\n                --manifest cli `\n                --file-description \'Repo AutoPull\' `\n                --product-name \'Repo AutoPull\' `\n                --original-filename \'RepoAutoPull.exe\' `\n                --file-version \'1.0.0.0\' `\n                --product-version \'1.0.0.0\'\n            if ($LASTEXITCODE -ne 0) { throw \'go-winres resource generation failed.\' }\n        }\n\n        & go vet ./...\n        if ($LASTEXITCODE -ne 0) { throw \'go vet failed.\' }\n\n        # -buildvcs=false keeps the single-file EXE reproducible across commits\n        # when the actual wrapper/script/resource inputs have not changed.\n        & go build -buildvcs=false -trimpath -ldflags \'-s -w\' -o $Output .\n        if ($LASTEXITCODE -ne 0) { throw \'go build failed.\' }\n    }\n    finally { Pop-Location }\n}\nfinally {\n    Remove-Item -LiteralPath $EmbeddedScript -Force -ErrorAction SilentlyContinue\n}\n\nWrite-Host "Built: $Output" -ForegroundColor Green\n')
write('Repo_AutoPull/README.txt', 'REPO AUTOPULL\n=============\n\nRepo AutoPull watches one local Git repository, checks its upstream branch at a chosen interval, safely updates it, and can run post-update actions.\n\nSTART\n-----\nRun:\n  Start Repo AutoPull.cmd\n\nThe launcher shows:\n  1. Start monitoring\n  2. Configure\n\nPressing Enter chooses Start. On first run, configuration opens automatically.\n\nCONFIGURATION\n-------------\nConfiguration is split into five sections:\n  1. Repository\n  2. Check interval\n  3. Pull behavior\n  4. Post-pull commands\n  5. Launch after commands\n\nPressing Enter at an existing setting keeps it unchanged.\n\nINTERVALS\n---------\nExamples accepted:\n  30\n  30s\n  30 sec\n  30 seconds\n  5m\n  5 min\n  5 minutes\n  1h\n  1 hour\n\nA number without a unit means seconds.\n\nPULL BEHAVIOR\n-------------\nTwo safe normal update modes are available:\n\n1. Preserve local tracked edits automatically (recommended)\n   git pull --ff-only --autostash\n\n2. Require a clean tracked worktree\n   git pull --ff-only\n\nInteractive recovery can be enabled/disabled. When enabled, a failed pull shows the real Git error and offers:\n  1. Retry\n  2. Show Git status + stash list\n  3. Stash tracked local changes and retry\n  4. Reset tracked files to the upstream branch (DESTRUCTIVE; requires typing RESET)\n  5. Skip and keep monitoring\n\nThe destructive reset is never automatic. It does not remove untracked files.\n\nCUSTOM COMMANDS\n---------------\nCustom commands are ordered and each command has a shell:\n  - PowerShell\n  - CMD / batch\n\nExisting pre-v5 commands are migrated as CMD commands for compatibility.\n\nNew/edit command input supports:\n  1. Clipboard contents (recommended for multi-line scripts)\n  2. One-line input\n  3. Multi-line input (finish with .done)\n\nPowerShell commands support variables, pipelines and cmdlets. Example:\n\n  $apk = Get-ChildItem .\\app\\build\\outputs\\apk -Recurse -Filter *.apk |\n      Where-Object FullName -Match "arm64-v8a" |\n      Select-Object -First 1\n\n  Copy-Item $apk.FullName .\\Artemis-Plus-debug-arm64.apk -Force\n\nEvery custom command runs with the watched repository as its working directory.\n\nPOST-UPDATE ORDER\n-----------------\n  fetch\n  -> pull / recovery\n  -> npm run build (optional)\n  -> custom command 1\n  -> custom command 2\n  -> ...\n  -> selected file launch (optional)\n  -> Windows notification\n\nIf build or a custom command fails, later post-update steps are skipped.\n\nSTANDALONE EXE - PORTABLE CONFIG\n--------------------------------\nRepoAutoPull.exe contains the same PowerShell logic in one Windows x64 executable.\n\nEach physical copy of RepoAutoPull.exe has its OWN configuration file beside it:\n\n  RepoAutoPull.exe\n  RepoAutoPull.config.json\n\nThat means you can make separate folders/copies for different repositories, for example:\n\n  RepoAutoPull-Etsy\\\n    RepoAutoPull.exe\n    RepoAutoPull.config.json\n\n  RepoAutoPull-Artemis\\\n    RepoAutoPull.exe\n    RepoAutoPull.config.json\n\nChanging one copy\'s repository, interval, commands, pull mode, or launch settings does not change the other copy.\n\nONE-TIME LEGACY MIGRATION\n-------------------------\nWhen a standalone EXE has no RepoAutoPull.config.json beside it yet, it checks for old configuration in this order:\n\n  1. Repo-AutoPull.config.json beside the EXE\n  2. %APPDATA%\\RepoAutoPull\\Repo-AutoPull.config.json\n\nIf found, it copies that configuration beside the EXE as RepoAutoPull.config.json once. After that the local portable file is the source of truth.\n\nThe EXE intentionally does NOT silently fall back to shared AppData configuration. If the folder containing RepoAutoPull.exe is not writable, it displays an error and asks you to move/copy the EXE to a writable folder.\n\nThe source .cmd + .ps1 launcher continues to store Repo-AutoPull.config.json beside Repo-AutoPull.ps1.\n\nICON\n----\nRepoAutoPull.exe has an embedded Windows application icon (repository/folder + sync/pull arrows). The source icon assets are under:\n\n  Repo_AutoPull\\assets\\RepoAutoPull.ico\n  Repo_AutoPull\\assets\\RepoAutoPull.png\n\nThe EXE also carries Windows file metadata:\n  Product name      : Repo AutoPull\n  File description  : Repo AutoPull\n  Original filename : RepoAutoPull.exe\n\nSAFETY\n------\nNormal updates never use reset --hard or force pull. The optional recovery reset is clearly marked DESTRUCTIVE, requires an explicit menu choice plus typing RESET, and is never performed automatically.\n\nRepo AutoPull refuses to automatically merge diverged histories.\n')
write('tools/repo-autopull-exe/README.md', '# Repo AutoPull standalone EXE\n\nThis directory contains the reproducible source for `Repo_AutoPull/RepoAutoPull.exe`.\n\nThe Go wrapper embeds `Repo-AutoPull.ps1`, extracts it to a temporary directory at runtime, and launches Windows PowerShell.\n\n## Portable configuration\n\nEach physical EXE copy uses its own adjacent configuration file:\n\n```text\nRepoAutoPull.exe\nRepoAutoPull.config.json\n```\n\nThe wrapper passes that exact local path to the embedded PowerShell script. Different EXE copies in different folders therefore keep independent repository/settings state.\n\nIf the local portable config does not exist, the wrapper performs one-time migration from:\n\n1. `Repo-AutoPull.config.json` beside the EXE\n2. `%APPDATA%\\RepoAutoPull\\Repo-AutoPull.config.json`\n\nThe EXE does not fall back to a shared AppData config if its own folder is not writable; it exits with a clear message instead.\n\n## Windows resources\n\n`Repo_AutoPull/assets/RepoAutoPull.ico` is embedded into the EXE together with:\n\n- Product name: `Repo AutoPull`\n- File description: `Repo AutoPull`\n- Original filename: `RepoAutoPull.exe`\n- as-invoker CLI manifest\n\nThe generated `rsrc_windows_amd64.syso` is committed so ordinary builds do not need to download a resource compiler.\n\n## Build on Windows\n\nRun:\n\n```powershell\n.\\build.ps1\n```\n\nThe normal build reuses the committed `.syso` resource object.\n\nIf the icon or Windows metadata changes, regenerate the resource object with:\n\n```powershell\n.\\build.ps1 -RefreshResources\n```\n\nResource regeneration uses the pinned `github.com/tc-hib/go-winres@v0.3.3` tool, then the build script runs `go vet` and produces `Repo_AutoPull/RepoAutoPull.exe` for Windows x64.\n\nThe standalone EXE and script edition use the same ordered custom-command list, Git, build, launch, recovery, and notification behavior.\n')
write('tools/repo-autopull-exe/generate_icon.py', 'from pathlib import Path\nfrom PIL import Image, ImageDraw\nimport math\n\nROOT = Path(__file__).resolve().parents[2]\nASSETS = ROOT / "Repo_AutoPull" / "assets"\nASSETS.mkdir(parents=True, exist_ok=True)\n\nS = 512\nimg = Image.new("RGBA", (S, S), (0, 0, 0, 0))\nd = ImageDraw.Draw(img)\n\n# Dark rounded tile.\nm = 36\nd.rounded_rectangle([m, m, S - m, S - m], radius=96, fill=(28, 37, 54, 255))\n\n# Blue repository/folder.\nd.rounded_rectangle([105, 145, 245, 220], radius=24, fill=(68, 128, 196, 255))\nd.rounded_rectangle([92, 180, 420, 360], radius=44, fill=(57, 111, 177, 255))\nd.rounded_rectangle([112, 205, 400, 340], radius=32, fill=(66, 124, 191, 255))\n\n# Cyan sync arrows.\ncx, cy, r = 270, 270, 105\ncyan = (76, 211, 224, 255)\nlight = (129, 237, 245, 255)\nbbox = [cx - r, cy - r, cx + r, cy + r]\nd.arc(bbox, start=205, end=335, fill=cyan, width=30)\nd.arc(bbox, start=25, end=155, fill=light, width=30)\n\ndef arrowhead(angle_deg, color):\n    ang = math.radians(angle_deg)\n    tip = (cx + r * math.cos(ang), cy + r * math.sin(ang))\n    tangent = ang + math.pi / 2\n    back = (tip[0] - 42 * math.cos(tangent), tip[1] - 42 * math.sin(tangent))\n    left = (back[0] + 24 * math.cos(ang), back[1] + 24 * math.sin(ang))\n    right = (back[0] - 24 * math.cos(ang), back[1] - 24 * math.sin(ang))\n    d.polygon([tip, left, right], fill=color)\n\narrowhead(335, cyan)\narrowhead(155, light)\n\n# Pull/download mark.\nwhite = (235, 250, 252, 255)\nd.rounded_rectangle([248, 225, 292, 300], radius=18, fill=white)\nd.polygon([(226, 286), (314, 286), (270, 330)], fill=white)\n\npng_path = ASSETS / "RepoAutoPull.png"\nico_path = ASSETS / "RepoAutoPull.ico"\nimg.save(png_path)\nimg.save(\n    ico_path,\n    format="ICO",\n    sizes=[(16, 16), (24, 24), (32, 32), (48, 48), (64, 64), (128, 128), (256, 256)],\n)\nprint(f"Wrote {png_path}")\nprint(f"Wrote {ico_path}")\n')

ps_path = ROOT / 'Repo_AutoPull/Repo-AutoPull.ps1'
ps = ps_path.read_text(encoding='utf-8-sig')
old = '$ConfigPath = Join-Path $ConfigRoot "Repo-AutoPull.config.json"'
new = '$ExplicitConfigPath = [string]$env:REPO_AUTOPULL_CONFIG_PATH\n$ConfigPath = if (-not [string]::IsNullOrWhiteSpace($ExplicitConfigPath)) {\n    $ExplicitConfigPath\n} else {\n    Join-Path $ConfigRoot "Repo-AutoPull.config.json"\n}'
if old not in ps:
    raise SystemExit('ConfigPath anchor not found')
ps = ps.replace(old, new, 1)
ps_path.write_text(ps, encoding='utf-8-sig', newline='\n')

gitignore = ROOT / '.gitignore'
text = gitignore.read_text(encoding='utf-8')
needle = 'Repo_AutoPull/Repo-AutoPull.config.json\n'
addition = 'Repo_AutoPull/RepoAutoPull.config.json\n'
if addition not in text:
    if needle not in text:
        raise SystemExit('.gitignore anchor not found')
    text = text.replace(needle, needle + addition, 1)
gitignore.write_text(text, encoding='utf-8', newline='\n')
